-- quest_greeting holds one greeting per creature or gameobject in `ID` and `type`, and the server
-- sends it to the client unchanged, so the early greeting text stayed English on a client whose DBC
-- files are Chinese. Translate every greeting that still carries English.
START TRANSACTION;
UPDATE `quest_greeting` SET `Greeting` = '一股邪恶的腐化已渗入西部荒野。当我还在洛丹伦的战场上尽忠职守时，这些本分的农场就被人侵占，成了暴徒和杀人犯的藏身处。人民军需要你的帮助。' WHERE `ID` = 234 AND `type` = 0 AND `Greeting` = 'A foul corruption has crept into Westfall.  While I was upholding my duty on the battlefields of Lordaeron these honest farms were overrun and made into hide-outs for thugs and murderers. The People''s Militia needs your help.';
UPDATE `quest_greeting` SET `Greeting` = '欢迎来到我们简陋的家！见到友善的面孔总是让人高兴。你的手臂真结实。我和我丈夫一直在农场里找人帮忙。好人都走得差不多了，想找个能干活的帮手可不容易。' WHERE `ID` = 235 AND `type` = 0 AND `Greeting` = 'Welcome to our humble abode!  It''s always nice to see a friendly face.  And what strong arms you have.  My husband and I are always looking for help around the farm.  Now that most the good folk have left, it''s hard to find an able body to help out.';
UPDATE `quest_greeting` SET `Greeting` = '这一带除了麻烦什么都没了。我曾劝那个傻瓜萨尔迪恩趁早离开，可他听不进去。但我可不是傻瓜。等我们把马车修好，维尔娜和我就走。' WHERE `ID` = 237 AND `type` = 0 AND `Greeting` = 'Nothing but trouble in these parts.  I tried to tell that fool Saldean to get out while he still could be he won''t hear of it.  But I ain''t no fool.  Verna and I are gonna mosey on out as soon as we get this wagon fixed.';
UPDATE `quest_greeting` SET `Greeting` = '有时我觉得天上悬着一大块乌云，净把霉运往我们头上浇。先是被赶出了自己的土地，现在连西部荒野都出不去。一切都乱成一团，总得有人做点什么。' WHERE `ID` = 238 AND `type` = 0 AND `Greeting` = 'Sometimes I think there''s a big gray cloud in the sky, just raining down bad luck upon us.  First, we''re driven off our land, and now we can''t even get out of Westfall.  Everything''s a mess.  Something needs to be done.';
UPDATE `quest_greeting` SET `Greeting` = '远近来冒险，$b遇见古人和怪人；$b但若想向我问事情，$b先得完成一件小事！' WHERE `ID` = 239 AND `type` = 0 AND `Greeting` = 'Adventure from lands far and near $bMeeting with folks both odd and queer $bBut if of me a question you ask $bYou must first complete a simple task!';
UPDATE `quest_greeting` SET `Greeting` = '唉，光这些新冒出来的麻烦就够我忙的了，维持秩序真是难上加难！希望你是带着好消息来的，$n……' WHERE `ID` = 240 AND `type` = 0 AND `Greeting` = 'Ach, it''s hard enough keeping order around here without all these new troubles popping up!  I hope you have good news, $n...';
UPDATE `quest_greeting` SET `Greeting` = '嘿，朋友。我叫雷米，从东边的赤脊山来，来这儿找生意，找生意。你有没有……有没有？' WHERE `ID` = 241 AND `type` = 0 AND `Greeting` = 'Hey there, friend.  My name''s Remy.  I''m from Redridge to the east, and came here looking for business, looking for business.  You got any...got any??';
UPDATE `quest_greeting` SET `Greeting` = '啊哈！你好，你好，$C 大师！来，坐下喝一杯。你眼里透着一股干练劲儿，我想跟我聊聊不会白费你的时间……' WHERE `ID` = 253 AND `type` = 0 AND `Greeting` = 'Aha!  Good day, good day, Master $C!  Come, sit down and have a drink.  You have an enterprising look in your eye, and I think you''ll find speaking to me worth your time...';
UPDATE `quest_greeting` SET `Greeting` = '你好，市民。你看起来像是有事要办的人——和暴风城军队有公务吗？' WHERE `ID` = 261 AND `type` = 0 AND `Greeting` = 'Hello, citizen.  You look like a $gman:woman; with a purpose - do you have business with the Stormwind Army?';
UPDATE `quest_greeting` SET `Greeting` = '稍息，$C。如果你只是路过，我建议你老老实实走大路，而且只在白天赶路。如果你在夜色镇有事，不妨把你的本事借给守夜人。我们的身手毋庸置疑，但人手实在太少。' WHERE `ID` = 264 AND `type` = 0 AND `Greeting` = 'At ease, $C.  If you are just passing though I suggest you stick to the roads and only travel by day. If your business is here in Darkshire, consider lending your abilities to The Night Watch.  Our skill is unquestionable but our numbers are small.';
UPDATE `quest_greeting` SET `Greeting` = '我早已察觉到你的到来，$n。星辰的轨迹里写明了这一切。' WHERE `ID` = 265 AND `type` = 0 AND `Greeting` = 'I have sensed your coming for quite some time, $n.  It was written in the pattern of the stars.';
UPDATE `quest_greeting` SET `Greeting` = '欢迎来到夜色镇。书记员达尔特雷为您效劳。有什么需要我帮忙的吗？' WHERE `ID` = 267 AND `type` = 0 AND `Greeting` = 'Welcome to the town of Darkshire.  Clerk Daltry at your service.  Can I be of some assistance?';
UPDATE `quest_greeting` SET `Greeting` = '你好，你好！欢迎来到我的厨房，先生/女士！猩红渡鸦旅店最上等的佳肴都出自这里。啊，闻闻这香气！' WHERE `ID` = 272 AND `type` = 0 AND `Greeting` = 'Hello, hello!  Welcome to my kitchen, $g sir : m''lady;!  This is where all of the Scarlet Raven Tavern''s finest delicacies are made.  Ah, just smell the wonderful aroma!';
UPDATE `quest_greeting` SET `Greeting` = '把门关好，$C。谁也说不准黑暗骑士什么时候又会经过。' WHERE `ID` = 273 AND `type` = 0 AND `Greeting` = 'Keep the door closed, $C.  Never know when the Dark Riders will be passing through again.';
UPDATE `quest_greeting` SET `Greeting` = '你好，先生/女士。坐下吧，饿了就吃点东西。别在意我低头忙着针线活——我在听你说话……' WHERE `ID` = 278 AND `type` = 0 AND `Greeting` = 'Hello, good $gsir:lady,.  Have a seat, and a meal if you''re hungry.  Don''t fret if I look busy with my needlework - I''m listening to you...';
UPDATE `quest_greeting` SET `Greeting` = '咦？！哦。你看起来不像迪菲亚盗贼……也不像守夜人的人。可怜可怜我这个苦命人吧？' WHERE `ID` = 288 AND `type` = 0 AND `Greeting` = 'Huh?!?  Oh.  You don''t look like a Defias thief...or a member of the Night Watch.  Take pity on a poor soul, will ya?';
UPDATE `quest_greeting` SET `Greeting` = '嗯？你好，年轻的 $C。外头游荡着那么多怪物，你还能找到这儿来，真是个勇敢的人！$B$B既然你来了，或许能帮帮一个老隐士……' WHERE `ID` = 289 AND `type` = 0 AND `Greeting` = 'Eh?  Greetings, young $C.  You''re a brave one to find your way here with all those wandering creatures about!$B$BWell now that you are here, maybe you can help an old hermit...';
UPDATE `quest_greeting` SET `Greeting` = '你好，旅行者。我的眼睛虽然不好使了，但一里地外就能听出 $c 的脚步声。我曾自豪地守卫暴风城多年，可眼睛一坏，就不得不退役了。' WHERE `ID` = 294 AND `type` = 0 AND `Greeting` = 'Hail, traveler.  My eyesight may be poor but I can sense the footsteps of a $c from a mile away.  For years I defended Stormwind with pride but once my eyes failed me, I was forced to retire.';
UPDATE `quest_greeting` SET `Greeting` = '欢迎来到阿佐拉之塔，年轻的 $C。我是泰奥克里特斯。$B$B你是来找我办事的吗？还是……也许是我找你办事？' WHERE `ID` = 313 AND `type` = 0 AND `Greeting` = 'Welcome to the Tower of Azora, young $C.  I am Theocritus.$B$BDo you have business with me?  Or...do I have business with you, perhaps?';
UPDATE `quest_greeting` SET `Greeting` = '我没时间闲聊，$N。我得赶在下雨前把这座桥修好。我每个工程都按时、按预算完成，现在也不会开始拖。' WHERE `ID` = 341 AND `type` = 0 AND `Greeting` = 'I don''t have much time for idle talk, $N.  I''ve got to get this bridge rebuilt before the rains come.  I''ve finished every project on-time and under budget and I''m not about to start slipping now.';
UPDATE `quest_greeting` SET `Greeting` = '你好，$N！欢迎来到我这座简陋的花园。最近天气一直很好。但愿它能保持下去，让我们有个丰收。' WHERE `ID` = 342 AND `type` = 0 AND `Greeting` = 'Hail, $N!  Welcome to my humble garden.  The weather has been perfect lately.  Let us hope it holds steady for a ripe harvest.';
UPDATE `quest_greeting` SET `Greeting` = '是哪位 $c 前来觐见暴风王国的莱克郡法庭？报上你在此镇的来意，$R。王国面临的兽人威胁太大，不容在闲谈中虚度时光。' WHERE `ID` = 344 AND `type` = 0 AND `Greeting` = 'Who is this $c who goes before the Court of Lakshire in the Kingdom of Stormwind?  State your business within this township, $R.  The orc threat to the Kingdom is far too great to squander time in idle conversation.';
UPDATE `quest_greeting` SET `Greeting` = '幸会，$C。如果你是来办事的，那就先给自己倒杯酒，我们再好好谈谈。' WHERE `ID` = 381 AND `type` = 0 AND `Greeting` = 'Well met, $C.  If you''re here for business, then get yourself a brew and we''ll have ourselves a talk.';
UPDATE `quest_greeting` SET `Greeting` = '我没空闲聊，市民，但如果你愿意帮我们对付兽人，我会给你安排点事做。' WHERE `ID` = 382 AND `type` = 0 AND `Greeting` = 'I don''t have time to chat, citizen, but if you''re willing to give us a hand against the orcs, then I''ll find a use for you.';
UPDATE `quest_greeting` SET `Greeting` = '不要惊慌，$r。我早已离开这个世界，但我无意伤害你的族人。我这一生见过了太多的死亡。我如今唯一的愿望就是安宁。也许你能帮我实现。' WHERE `ID` = 392 AND `type` = 0 AND `Greeting` = 'Do not be alarmed, $r.  I have long since passed from this land but I intend no harm to your kind.  I have witnessed too much death in my time.  My only wish now is for peace.  Perhaps you can help my cause.';
UPDATE `quest_greeting` SET `Greeting` = '嘿，伙计，能帮我个忙吗？我真是走投无路了……' WHERE `ID` = 415 AND `type` = 0 AND `Greeting` = 'Hey $Gbuddy:ma''am;, do you think you could give me a hand with something?  I''m really IN dire straits here...';
UPDATE `quest_greeting` SET `Greeting` = '你好，$C。这年头不太平啊，朋友，我们的镇子被围困了！黑石兽人从石堡要塞发起进攻，暗影蛛后盘踞在伊尔加拉之塔，赤脊豺狼人也在积蓄力量。希望你不是来度假的……' WHERE `ID` = 464 AND `type` = 0 AND `Greeting` = 'Hail, $C.  Ill times these are, my friend, for our town is besieged!  The Blackrock Orcs attack from Stonewatch Keep, the Shadowhides loom over the Tower of Ilgalar, and the Redridge Gnoll Pack gathers strength.  I hope you''re not here for a holiday...';
UPDATE `quest_greeting` SET `Greeting` = '你好，$c。如果你是库尔森上校的朋友，我就地砍了你！但如果你是来帮我们的，那就听我说……' WHERE `ID` = 469 AND `type` = 0 AND `Greeting` = 'Greetings, $c.  If you''re a friend of Colonel Kurzen then I''ll have you cut down where you stand! but if you''ve come to aid us, then lend an ear...';
UPDATE `quest_greeting` SET `Greeting` = '黑暗的时代已经来临，$c……我们很快就会失去一切……圣光将抛弃所有人，只留下真正行于圣光之下的人。' WHERE `ID` = 633 AND `type` = 0 AND `Greeting` = 'It''s dark times that have come, $c... All too soon will we lose everything... When the Light will forsake all but those who truly walk under the Light.';
UPDATE `quest_greeting` SET `Greeting` = '到处都是盗贼！$b$b太可怕了。山洞塌了下来，我想矿工公司的人全死了，包括我哥哥——那个工头。' WHERE `ID` = 656 AND `type` = 0 AND `Greeting` = 'There were thieves everywhere! $b$bIt was horrible.  The cave came down on us.  I think the mining company is all dead, including my brother, the Foreman.';
UPDATE `quest_greeting` SET `Greeting` = '你好。你找卡雷文家族有什么事？你是来协助卡雷文家族对抗亡灵的吗？' WHERE `ID` = 661 AND `type` = 0 AND `Greeting` = 'Greetings. What business have you with the Carevin family? Do you seek to assist the Carevins in their battle against the undead?';
UPDATE `quest_greeting` SET `Greeting` = '卡雷文家族为圣光之下的胜利而战。我在圣光之下的职责，就是在这场对抗亡灵的战争中献出生命。卡雷文大人派我肃清暮色森林里那些邪恶的狼人。也许你愿意助我一臂之力？' WHERE `ID` = 663 AND `type` = 0 AND `Greeting` = 'The Carevin family fights for victory under the Light. My duty under the Light is to give my life in their battle against against the undead. Master Carevin has tasked me with the extermination of the vile worgen in Duskwood. Perhaps you would assit me?';
UPDATE `quest_greeting` SET `Greeting` = '你好，$c！打猎的好天气，不是吗？我自己打野猪运气一直不错。也许你也想来一枪？' WHERE `ID` = 714 AND `type` = 0 AND `Greeting` = 'Greetings, $c! Fine day for hunting, wouldn''t you say? I''ve been having more than a little luck with boars, myself. Perhaps you''d like a shot?';
UPDATE `quest_greeting` SET `Greeting` = '丛林里又一个好天气！这会是场大猎，我能感觉到。等巴尼尔把枪擦完，我就带狩猎队钻进那些盘绕的藤蔓深处。对老兵来说，这样退休也不算太糟，是吧？' WHERE `ID` = 715 AND `type` = 0 AND `Greeting` = 'Another fine day in the jungle!  It''s going to be quite a hunt,  I can feel it.  Once Barnil is done cleaning the guns, I''m taking the hunting party deep into the twisting vines.  Not such a bad way for an old war vet to spend his retirement, eh?';
UPDATE `quest_greeting` SET `Greeting` = '在这儿走路看着点，孩子。你也许不是我们的人，但你要是乱了规矩，我照样拿棍子抽你！' WHERE `ID` = 733 AND `type` = 0 AND `Greeting` = 'You watch where you step around here, $Gson:lass;.  You might not be a part of our outfit, but that doesn''t mean I won''t take a cane to you if you fall out of line!';
UPDATE `quest_greeting` SET `Greeting` = '哟，你好啊。看样子你不反对赚点钱，是吧？从你眼神里我就能看出来。我是凯博克，艾泽拉斯地区的事务总管，如果你想要财富，也许我能安排。' WHERE `ID` = 737 AND `type` = 0 AND `Greeting` = 'Well, hello there. You seem like you wouldn''t be opposed to making some coin, hm? I can tell from the look in your eyes. I am Mogul Kebok, overseer of operations in Azeroth, and if it is riches you seek, perhaps I can make arrangements.';
UPDATE `quest_greeting` SET `Greeting` = '$C，嗯？我是克拉泽克，雷维尔加兹男爵的秘书。这丛林里外发生的事我全知道。也许你有兴趣知道棘齿城石油的价格？不想？那也许是找工作？这我也能帮上忙。' WHERE `ID` = 773 AND `type` = 0 AND `Greeting` = '$C, eh? I am Krazek, Baron Revilgaz''s secretary. I know everything about the goings on in this jungle and beyond. Perhaps you''d be interested in knowing the going price on oil in Ratchet? No? Looking for work, maybe? I can help you there.';
UPDATE `quest_greeting` SET `Greeting` = '你好，孩子。我是格雷林·白胡子。我来这里是为了查清冷脊谷里越来越多的巨魔带来的威胁。我查到了什么？有点让人不安……' WHERE `ID` = 786 AND `type` = 0 AND `Greeting` = 'Greetings, $g lad : girl;. I''m Grelin Whitebeard. I''m here to examine the threat posed by the growing numbers of trolls in Coldridge Valley. What have I found? It''s a bit troubling...';
UPDATE `quest_greeting` SET `Greeting` = '你好，$c。平常我都在街上巡逻，照看暴风城的百姓，可许多暴风城卫兵都在别处作战。所以我就被派到这儿，发放赏金，其实我更愿意去巡逻……' WHERE `ID` = 823 AND `type` = 0 AND `Greeting` = 'Hello there, $c.  Normally I''d be out on the beat looking after the folk of Stormwind, but a lot of the Stormwind guards are fighting in other lands.  So here I am, deputized and offering bounties when I''d rather be on patrol...';
UPDATE `quest_greeting` SET `Greeting` = '什么事情让你来到莱克郡法庭，面见尊敬的所罗门地方法官？' WHERE `ID` = 900 AND `type` = 0 AND `Greeting` = 'What business brings you before the Court of Lakeshire and the Honorable Magistrate Solomon?';
UPDATE `quest_greeting` SET `Greeting` = '如果说时间教会了我什么，那就是没有哪项任务是无趣的。守卫萨多尔大桥本该是件轻松差事。可主力部队都去跟联盟并肩作战了，我们在这里被压垮，丹莫德已经失守。' WHERE `ID` = 1071 AND `type` = 0 AND `Greeting` = 'If there''s one thing time has taught me it''s that no assignment is a dull one.  Protecting the Thandol Span should have been an easy task.  But with the brunt of the army fighting alongside the alliance, we were overwhelmed here and Dun Modr has fallen.';
UPDATE `quest_greeting` SET `Greeting` = '你知道吗，我一直想当个勘探员，可我天生对数字敏感，公会认定我最适合管账！年轻时天天学啊，学啊……' WHERE `ID` = 1105 AND `type` = 0 AND `Greeting` = 'You know, I always wanted to be a Prospector, but I was born with a head for numbers and the Guild decided I would be best suited to keep the books! Studying, studying, every day of my youth...';
UPDATE `quest_greeting` SET `Greeting` = '你好啊，市民。我叫布伦特诺斯，准确说是布伦特诺斯地方法官。我负责照看塞尔萨玛的安宁，跟你说，我们这儿总需要多几双结实的手臂！' WHERE `ID` = 1139 AND `type` = 0 AND `Greeting` = 'Well hello there, citizen. The name''s Bluntnose, Magistrate Bluntnose, to be precise. I''m charged with overseeing the well-being of Thelsamar, and believe you me, we could always use another strong set of arms around here!';
UPDATE `quest_greeting` SET `Greeting` = '如果你是为吃的来的，欢迎！整个暴风城……不，整个艾泽拉斯都找不出更好的菜！$B$B如果你是为别的事来的，那就请长话短说。我还有十几道菜在备着，每道都得照看。' WHERE `ID` = 1141 AND `type` = 0 AND `Greeting` = 'If you''re here for the food, then welcome!  You won''t find finer dining in all of Stormwind...or Azeroth!$B$BIf you''re here on other matters, then please be brief.  I have a dozen dishes in preparation, and must care for each.';
UPDATE `quest_greeting` SET `Greeting` = '如果你愿意听那些让你汗毛倒竖、裤裆发潮的故事，那就倒杯酒坐下听一会儿……' WHERE `ID` = 1239 AND `type` = 0 AND `Greeting` = 'If you''re willing to endure tales that will shiver your timbers and sog your skivvies, then get yourself a drink and sit for a spell...';
UPDATE `quest_greeting` SET `Greeting` = '穴居人！我发誓众神把他们放到这片土地上就是为了折磨我！矿井往里挖了四寸，就得从穴居人那儿后退两尺！' WHERE `ID` = 1254 AND `type` = 0 AND `Greeting` = 'Troggs! I swear the gods put them in this land only to torment me! Four inches deeper into the mines, then two feet back from the troggs!';
UPDATE `quest_greeting` SET `Greeting` = '欢迎来到雷酒酿酒厂，这是亲爱的老父亲阿基鲁斯·雷酒创办的。自从我哥哥格里姆酒几个收获季前醉醺醺地失踪以后，这地方就由我撑着。' WHERE `ID` = 1267 AND `type` = 0 AND `Greeting` = 'Welcome to the Thunderbrew Distillery, founded by dear ol'' pappy, Arkilus Thunderbrew.  I''ve been keeping the place running ever since my older brother, Grimbooze, disappeared in a drunken haze a few harvests ago.';
UPDATE `quest_greeting` SET `Greeting` = '哟，这不是个血气方刚的年轻 $c 吗，肯定是听说了我在战场上的事迹才来的！$B$B现在没工夫讲故事，有太多重要的大事要做！所以，如果你想追求荣耀，今天算你走运……' WHERE `ID` = 1343 AND `type` = 0 AND `Greeting` = 'Well, if it isn''t a young, bristling $c, no doubt drawn here by talk of my exploits in fields of battle!$B$BNo time for stories now, for there are great, important deeds that need doing!  So if you''re looking for glory, then luck shines on you today...';
UPDATE `quest_greeting` SET `Greeting` = '虽然这些废墟上的活儿正处在淡季，但我相信不会持续太久。在此期间，我正需要你这样的人。愿意协助矮人探险者协会吗？' WHERE `ID` = 1344 AND `type` = 0 AND `Greeting` = 'Although we''re trudging through a slow period at these ruins, I''m confident it won''t last long.  But in the meantime, I could use someone like you.  Would you like to aid the Dwarven Explorers'' Guild?';
UPDATE `quest_greeting` SET `Greeting` = '我正忙着办一件非常重要的事。勘探员的活儿。除非你有同样重要的事要说——我深表怀疑——否则请恕我失陪。' WHERE `ID` = 1356 AND `type` = 0 AND `Greeting` = 'I''m in the middle of a very important task.  Prospector business.  Unless you have something equally important to say, which I doubt, then you''ll have to excuse me.';
UPDATE `quest_greeting` SET `Greeting` = '该死的酿酒师联盟！最好的原料都让他们占了，我们却只能在这儿刨粮食和啤酒花！$B$B我真想让他们尝尝苦头……' WHERE `ID` = 1374 AND `type` = 0 AND `Greeting` = 'Curse that Brewers'' League!  They have access to all the best ingredients, while we''re stuck here grubbing for grain and hops!$B$BI really would like to give them some bitter tasting justice...';
UPDATE `quest_greeting` SET `Greeting` = '开蒸汽坦克可不是谁都能干的，得有铁一般的手劲和钢铁般的胆量……幸好我两样都有！你呢？你的胆量怎么样？想证明给我看吗？' WHERE `ID` = 1377 AND `type` = 0 AND `Greeting` = 'Driving a Steam Tank isn''t for everyone.  It takes an iron grip and nerves of steel...lucky I have both!  How about you?  How''s your mettle?  Want to prove it to me?';
UPDATE `quest_greeting` SET `Greeting` = '暴风城皇家图书馆里的知识，你在别处可找不到更多的了！' WHERE `ID` = 1440 AND `type` = 0 AND `Greeting` = 'You''ll not find a greater cache of knowledge than in the Royal Library of Stormwind!';
UPDATE `quest_greeting` SET `Greeting` = '你好，$C。向东走去壁垒的路上要多加小心。最近的侦察报告显示那一带天灾的活动有所增加，务必谨慎。' WHERE `ID` = 1495 AND `type` = 0 AND `Greeting` = 'Greetings, $C.  Be wary as you travel east toward The Bulwark.  Recent surveillance reports indicate increased Scourge activity in that area, so exercise caution.';
UPDATE `quest_greeting` SET `Greeting` = '啊，你来了！我有任务要交给你，就不必浪费时间解释它们有多关键了。仔细听。' WHERE `ID` = 1499 AND `type` = 0 AND `Greeting` = 'Ah, you there!  I have tasks to give, and I need not waste time explaining their crucial nature.  Listen close.';
UPDATE `quest_greeting` SET `Greeting` = '希望你一切都好，至少大体上还好。$B$B坐下歇会儿，听听我的故事。当然，这是个悲剧，但我希望它最终以复仇收场！' WHERE `ID` = 1500 AND `type` = 0 AND `Greeting` = 'I hope you''re well, all things considered.$B$BSit for a spell, and hear my tale.  It''s a tragedy, of course, but one I hope will end in revenge!';
UPDATE `quest_greeting` SET `Greeting` = '血色十字军正在侵占我们的家园。那些狂热的蠢货不知道，黑暗女士忠实的仆人会让他们走向灭亡。' WHERE `ID` = 1515 AND `type` = 0 AND `Greeting` = 'The Scarlet Crusade is encroaching on our homeland.  The foolish zealots do not realize that the loyal servants of The Dark Lady shall see to their demise.';
UPDATE `quest_greeting` SET `Greeting` = '黑暗女士已经发出了挑战，就看我们能不能接住了。' WHERE `ID` = 1518 AND `type` = 0 AND `Greeting` = 'The Dark Lady has put forth the challenge.  It is up to us to meet it.';
UPDATE `quest_greeting` SET `Greeting` = '你好，我是巴罗斯·阿历克斯顿，暴风城的城市建筑师。' WHERE `ID` = 1646 AND `type` = 0 AND `Greeting` = 'Greetings, I am Baros Alexston, City Architect of Stormwind.';
UPDATE `quest_greeting` SET `Greeting` = '这边，你这没用的东西……！想干点有用的事，就快点听！' WHERE `ID` = 1719 AND `type` = 0 AND `Greeting` = 'Over here, you worthless...! If you want to do something useful, listen quick!';
UPDATE `quest_greeting` SET `Greeting` = '这卷卷轴汇集了各种后勤与战略情报，还有一些加密的往来信件。' WHERE `ID` = 1738 AND `type` = 1 AND `Greeting` = 'This collection of scrolls contains various logistic and strategic information, as well as coded correspondences.';
UPDATE `quest_greeting` SET `Greeting` = '这卷卷轴汇集了各种后勤与战略情报，还有一些加密的往来信件。' WHERE `ID` = 186420 AND `type` = 1 AND `Greeting` = 'This collection of scrolls contains various logistic and strategic information, as well as coded correspondences.';
UPDATE `quest_greeting` SET `Greeting` = '我是伯瓦尔·弗塔根，暴风城的大领主。' WHERE `ID` = 1748 AND `type` = 0 AND `Greeting` = 'I am Bolvar Fordragon, Highlord of Stormwind.';
UPDATE `quest_greeting` SET `Greeting` = '我们大半生在奔波中度过，和平岁月的记忆越来越遥远了。' WHERE `ID` = 1776 AND `type` = 0 AND `Greeting` = 'We spent so much of our lives in flight, memories of peaceful times grow evermore distant.';
UPDATE `quest_greeting` SET `Greeting` = '黑暗女士已经发出挑战。现在就看皇家药剂师协会研发出新瘟疫了。我们要让阿尔萨斯和他那支可悲的军队跪地求饶。' WHERE `ID` = 1937 AND `type` = 0 AND `Greeting` = 'The Dark Lady has put the challenge forth.  Now it is up to the Royal Apothecary Society to develop a new plague.  We shall bring Arthas and his wretched army to their knees.';
UPDATE `quest_greeting` SET `Greeting` = '肯瑞托根本没听我的警告！联盟不过是个空壳。阿鲁高是个鲁莽的蠢货。' WHERE `ID` = 1938 AND `type` = 0 AND `Greeting` = 'The Kirin Tor did not heed my warnings!  The Alliance is a sham.  Arugal is a wreckless fool.';
UPDATE `quest_greeting` SET `Greeting` = '我和我兄弟在执行一项重要任务，却被困在这座农舍里。亡灵哨兵需要你的帮助。' WHERE `ID` = 1950 AND `type` = 0 AND `Greeting` = 'My brother and I are on a vital mission, but we are holed up in this farmhouse.  The Deathstalkers need your help.';
UPDATE `quest_greeting` SET `Greeting` = '你好，$C。你既然来到这里，就一定知道希尔斯布莱德到处都是我们的敌人。要活下去，被遗忘者必须把他们击退！' WHERE `ID` = 1952 AND `type` = 0 AND `Greeting` = 'Hello, $C.  If you''re here, then you must know that Silverpine is saturated with our enemies.  To survive, the Forsaken must drive them back!';
UPDATE `quest_greeting` SET `Greeting` = '我从小受的教育就是为了服务公众，做人民的代表。我的本事不在刀枪或手艺上，而在言辞与说服。' WHERE `ID` = 1977 AND `type` = 0 AND `Greeting` = 'I was bred and educated for public service. A representative of the people. My skill was not in arms or crafts, but in words and persuasion';
UPDATE `quest_greeting` SET `Greeting` = '皇家药剂师协会必将响应黑暗女士的召唤，揭开新瘟疫的奥秘，把阿尔萨斯和他那支异端天灾军团彻底赶出这个世界。' WHERE `ID` = 2055 AND `type` = 0 AND `Greeting` = 'The Royal Apothecary Society shall heed The Dark Lady''s call to uncover the New Plague and drive Arthas and his heathen Scourge Army from the world once and for all.';
UPDATE `quest_greeting` SET `Greeting` = '这口大锅里翻腾着浓稠的绿色气泡，不明的头骨、骨头和器官在黏稠的汤里浮沉……$B$B慢悠悠浮上水面的，是两个曾经强大的巨魔的头骨：$B$B甘祖拉和奈兹里奥克。' WHERE `ID` = 2076 AND `type` = 1 AND `Greeting` = 'This cauldron churns with thick, green bubbles.  Skulls, bones and organs of unknown creatures swim within its viscous broth...$B$BAnd rising lazily to the surface are the skulls of two, once mighty trolls:$B$BGan''zulah and Nezzliok.';
UPDATE `quest_greeting` SET `Greeting` = '泰达希尔的诞生是一项伟大的成就，但如今世界必须改变，才能恢复平衡。' WHERE `ID` = 2080 AND `type` = 0 AND `Greeting` = 'The creation of Teldrassil was a grand achievement, but now the world must shift to regain its balance.';
UPDATE `quest_greeting` SET `Greeting` = '攻城器械是每个驾驶员的骄傲！' WHERE `ID` = 2092 AND `type` = 0 AND `Greeting` = 'Siege engines are the pride of every pilot!';
UPDATE `quest_greeting` SET `Greeting` = '你好，$c。我现在有点为难，兽皮快用完了。' WHERE `ID` = 2094 AND `type` = 0 AND `Greeting` = 'Greetings, $c. I''m in a bit of a pinch right now, running very low on hides.';
UPDATE `quest_greeting` SET `Greeting` = '情报……靠着斥候和密探，我们掌控着洛丹伦的信息流向。天灾的动向、他们的据点，全在我们的眼皮底下……' WHERE `ID` = 2121 AND `type` = 0 AND `Greeting` = 'Information... With our scouts and agents, we control the flow of information in Lordaeron. Scourge movements, their holdings, all underneath our watchful eyes...';
UPDATE `quest_greeting` SET `Greeting` = '为了效忠黑暗女士和瓦里玛萨斯，我们必须推进对人类的攻势。' WHERE `ID` = 2215 AND `type` = 0 AND `Greeting` = 'In order to serve the Dark Lady and Varimathras we need to advance the front on the Human Infestation.';
UPDATE `quest_greeting` SET `Greeting` = '我们离黑暗女士如此渴望的新瘟疫只差一步了。' WHERE `ID` = 2216 AND `type` = 0 AND `Greeting` = 'We are but so close to developing the New Plague that our Dark Lady desires with such fervor.';
UPDATE `quest_greeting` SET `Greeting` = '想想看，酋长出生成长的地方就在这么近。' WHERE `ID` = 2229 AND `type` = 0 AND `Greeting` = 'To think, the place the Warchief was born and raised lies so close.';
UPDATE `quest_greeting` SET `Greeting` = '希望你是来干活的，$C。我们有很多事要做，而部落、辛迪加和食人魔都不会来帮我们。' WHERE `ID` = 2263 AND `type` = 0 AND `Greeting` = 'I hope you''re here to work, $C.  We have a lot to do and the Horde, the Syndicate and the Ogres aren''t going to help us.';
UPDATE `quest_greeting` SET `Greeting` = '当初受封南海镇地方法官时，我为自己这么年轻就得到这样的职位而欣喜若狂。$B$B可如今到了这儿，我倒在想，也许当初在暴风城整理文书还更好些。' WHERE `ID` = 2276 AND `type` = 0 AND `Greeting` = 'When I was first offered the title of Southshore Magistrate I was elated to have earned such a commission so early in my career.$B$BBut now that I''m here, I wonder if I''d have been better off shuffling papers in Stormwind.';
UPDATE `quest_greeting` SET `Greeting` = '我有很多工作要做。你是来协助我研究的吗？' WHERE `ID` = 2277 AND `type` = 0 AND `Greeting` = 'I have a great deal of work to do.  Are you here to aid me with my research?';
UPDATE `quest_greeting` SET `Greeting` = '我们家族收藏的珠宝与艺术品，在暴风城所有贵族里都是最好的！$B$B而且我们一直都想让藏品再多一些……' WHERE `ID` = 2285 AND `type` = 0 AND `Greeting` = 'My family boasts the finest collection of jewelry and objects of fine art among all the nobles of Stormwind!$B$BAnd we are always wishing to increase the size our collection...';
UPDATE `quest_greeting` SET `Greeting` = '啊，闻闻这海风的咸味！回到我们的母港藏宝海湾总是让人愉快。' WHERE `ID` = 2487 AND `type` = 0 AND `Greeting` = 'Ah, smell the fine salt air!  ''Tis always nice to return to our home port of Booty Bay.';
UPDATE `quest_greeting` SET `Greeting` = '嗯？你找宁博亚有事？' WHERE `ID` = 2497 AND `type` = 0 AND `Greeting` = 'Eh?  You have business with Nimboya?';
UPDATE `quest_greeting` SET `Greeting` = '什么什么？！我们都是为了赚头……光站着发呆可赚不到。' WHERE `ID` = 2498 AND `type` = 0 AND `Greeting` = 'What what?!?  We all have profit to make... and we won''t do it by standing idle.';
UPDATE `quest_greeting` SET `Greeting` = '喂！你是来玩指节游戏的吗？' WHERE `ID` = 2501 AND `type` = 0 AND `Greeting` = 'Oy!  You here for a game of knuckles?';
UPDATE `quest_greeting` SET `Greeting` = '你好！神灵说你来了，是来帮我们酋长的。他们说得可响了。' WHERE `ID` = 2519 AND `type` = 0 AND `Greeting` = 'Hello!  The spirits say you here to aid my chief.  Say it loud, they do.';
UPDATE `quest_greeting` SET `Greeting` = '呀哈……你可别浪费我的时间，伙计！' WHERE `ID` = 2546 AND `type` = 0 AND `Greeting` = 'Yarrr... ye best not be trifling with my time, matey!';
UPDATE `quest_greeting` SET `Greeting` = '我们在避难谷还守着阿拉希高地所剩不多的激流堡领地。而且我们正在失守……$B$B如果你有话要说，但愿是好消息。' WHERE `ID` = 2700 AND `type` = 0 AND `Greeting` = 'We at Refuge Pointe hold one of the few remaining patches of Stromgarde territory in the Arathi Highlands.  And we''re losing ground...$B$BIf you have words for me, then I hope they are good tidings.';
UPDATE `quest_greeting` SET `Greeting` = '多亏了酋长，即使在这座旧监狱的废墟里，希望仍未熄灭，部落正在重新崛起。' WHERE `ID` = 2706 AND `type` = 0 AND `Greeting` = 'Thanks to the Warchief, even here in the ruins of our former prison, some hope remains, and the Horde rises anew.';
UPDATE `quest_greeting` SET `Greeting` = '这块木板上钉着几张粗制滥造的悬赏告示。' WHERE `ID` = 2713 AND `type` = 1 AND `Greeting` = 'This wooden board holds roughly-made wanted posters.';
UPDATE `quest_greeting` SET `Greeting` = '退后！别过来！我这袋子里装满了炸药，我可不怕用！我把我们全炸飞！$B$B哦，算了。我还以为你是别人……' WHERE `ID` = 2785 AND `type` = 0 AND `Greeting` = 'Back away!  Stay back!  I have a pack full of blastpowder and I''m not afraid to use it!  I''ll blow us all away!$B$BOh, never mind.  I thought you were someone else....';
UPDATE `quest_greeting` SET `Greeting` = '欢迎来到骨握的符文与厄运，$c。可以看，别碰。$B$B这里的有些知识不是给……未入门者准备的。' WHERE `ID` = 2786 AND `type` = 0 AND `Greeting` = 'Welcome to Bonegrip''s Runes and Dooms, $c.  You may look, but do not touch.$B$BSome of the knowledge here is not meant for the...uninitiated.';
UPDATE `quest_greeting` SET `Greeting` = '你会在这片荒芜之地游荡，一定是走投无路了，$c。跟我一样走投无路。$B$B又或者你是疯了才来的。疯了，跟我一样。' WHERE `ID` = 2817 AND `type` = 0 AND `Greeting` = 'You must be hard up to be wandering these Badlands, $c.  Hard up like me.$B$BOr maybe you''re here because you''re crazy.  Crazy, like me.';
UPDATE `quest_greeting` SET `Greeting` = '跟你说，$c，那真是仓促得够呛。凡是没钉死的、能快点拆下来的，我们都搬走了。所以现在物资有点紧。' WHERE `ID` = 2860 AND `type` = 0 AND `Greeting` = 'It was quite a departure, let me tell you, $c. We were grabbing whatever wasn''t nailed down or could be removed quickly. We''re a little spare on supplies because of it.';
UPDATE `quest_greeting` SET `Greeting` = '那些混蛋夜里就冲我们来了，当时我们刚喝了几杯。要不然我们准能收拾他们，没问题。$B$B现在他们都死了……只剩我们几个。' WHERE `ID` = 2910 AND `type` = 0 AND `Greeting` = 'Bastards came right at us at night, after we''d gotten a few drinks in us. Otherwise, we could''ve taken ''em, count on it.$B$BEveryone''s dead now... except a few of us.';
UPDATE `quest_greeting` SET `Greeting` = '嘿，$N。$B$B洛特威尔算不上我见过的最有眼力的老板，可他真是全身心扑在工作上。扑得太投入，有时候他的仆人连饭都吃不上，工钱也拿不到。$B$B<卢西恩朝洛特威尔皱了皱眉。>$B$B但这不代表你就得跟着受罪。' WHERE `ID` = 2920 AND `type` = 0 AND `Greeting` = 'Hey there, $N.$B$BLotwil''s not the most perceptive boss I''ve had. He actually gets really involved with his work. So much so that sometimes his servants don''t eat, or get paid.$B$B<Lucien frowns over at Lotwil.>$B$BBut that doesn''t mean you should suffer.';
UPDATE `quest_greeting` SET `Greeting` = '你来得真是时候，$c。$B$B我叫洛特威尔·维利亚图斯，奥秘学、炼金术与工程科学启蒙协会的创始成员：我们想让艾泽拉斯的各门智慧科学融汇成一所完整的学院。' WHERE `ID` = 2921 AND `type` = 0 AND `Greeting` = 'How perfect of you to come by, $c.$B$BMy name is Lotwil Veriatus, founding member of the Enlightened Assembly of Arcanology, Alchemy, and Engineering Sciences: we seek to blend the intelligent sciences of Azeroth together into one comprehensive school.';
UPDATE `quest_greeting` SET `Greeting` = '腐化悄悄侵入了自然的林地。无论如何都要保护这片森林。' WHERE `ID` = 2930 AND `type` = 0 AND `Greeting` = 'Corruption sneaks into nature''s grove.  The forest must be protected at all costs.';
UPDATE `quest_greeting` SET `Greeting` = '你好，$c。这些年我见过许多想向部落证明自己的年轻牛头人。别忘了，热情代替不了智慧与经验。' WHERE `ID` = 2981 AND `type` = 0 AND `Greeting` = 'Hail, $c. In my years I have seen many eager tauren who wish to prove their worth to the tribe. It should not be forgotten that eagerness is no substitute for wisdom and experience.';
UPDATE `quest_greeting` SET `Greeting` = '迅跑者的职责，是保证所有穿越莫高雷平原的旅人平安。谁要是威胁牛头人家园的安全，就要承担我们的惩罚。' WHERE `ID` = 2988 AND `type` = 0 AND `Greeting` = 'The Outrunners'' duty is to ensure the safety of those who travel across the plains of Mulgore. Those that would threaten the safety of the tauren homeland risk punishment at our hands.';
UPDATE `quest_greeting` SET `Greeting` = '大地对我们的人民一向慷慨，$c。我们当为这份福气心存感激。' WHERE `ID` = 2993 AND `type` = 0 AND `Greeting` = 'The land has been good to our people, $c. We must be thankful for our good fortune.';
UPDATE `quest_greeting` SET `Greeting` = '牛头人是大地母亲的儿女，我们敬重她所有的孩子。就连被我们猎杀的野兽也值得珍视，它们的血肉滋养我们，皮毛为我们御寒。' WHERE `ID` = 3050 AND `type` = 0 AND `Greeting` = 'The tauren are sons and daughters of the Earthmother, and we show respect to all her children.  Even the beasts we slay are cherished, as their bodies give nourishment and their skins provide warmth.';
UPDATE `quest_greeting` SET `Greeting` = 'Throm''ka，$c。没多少时间说话，活儿还很多。' WHERE `ID` = 3139 AND `type` = 0 AND `Greeting` = 'Throm''ka, $c. There is little time for talk and much work to be done.';
UPDATE `quest_greeting` SET `Greeting` = '你有些事想谈，$c……来吧，坐我旁边。' WHERE `ID` = 3188 AND `type` = 0 AND `Greeting` = 'There is something you wish to discuss, $c... come, sit by me.';
UPDATE `quest_greeting` SET `Greeting` = '斧头的重量、战友的战吼、扑在脸上的鲜血。这些正是战士所渴求的，$n。我要以部落之名，用我的剑在贫瘠之地开出一条路来。' WHERE `ID` = 3337 AND `type` = 0 AND `Greeting` = 'The heft of an axe, the battlecry of your allies, the spray of blood in your face. These are the things a warrior craves, $n. I will carve out The Barrens with my sword in the name of the Horde.';
UPDATE `quest_greeting` SET `Greeting` = '土地、水与天空本为一体。是你的眼睛欺骗了你，让你看见了分隔。大地母亲就是这一切，甚至更多。' WHERE `ID` = 3338 AND `type` = 0 AND `Greeting` = 'The land, the water, and the sky are all as one. It is your eyes that deceive you with such separation. The Earthmother is all those things and more.';
UPDATE `quest_greeting` SET `Greeting` = '最好真有什么要紧事……' WHERE `ID` = 3339 AND `type` = 0 AND `Greeting` = 'This had better be good....';
UPDATE `quest_greeting` SET `Greeting` = '贫瘠之地蕴藏着丰富的物质，我们这些洛丹伦的药剂师或许能派上用场。' WHERE `ID` = 3390 AND `type` = 0 AND `Greeting` = 'The Barrens holds a wealth of substances for which we, the apothecaries or Lordaeron, may find use.';
UPDATE `quest_greeting` SET `Greeting` = '萨尔为我和我手下的兄弟们出力修建奥格瑞玛付了重酬，所以我就决定在这儿开个港口。我们的生意大多通过藏宝海湾和雷维尔加兹男爵。' WHERE `ID` = 3391 AND `type` = 0 AND `Greeting` = 'Thrall paid me and my boys well for helping out with the construction of Orgrimmar, so I decided to set up a port here. We do most of our business through Booty Bay and Baron Revilgaz.';
UPDATE `quest_greeting` SET `Greeting` = '要让我们的族人存续下去，就必须研究自然的法则，洞悉其中的奥秘。' WHERE `ID` = 3419 AND `type` = 0 AND `Greeting` = 'For our people to survive, we must study the ways of nature and learn its secrets.';
UPDATE `quest_greeting` SET `Greeting` = '要猎杀一头野兽，就得了解那头野兽，学习并尊重它的习性。$B$B不然就不叫打猎，只是杀生而已。' WHERE `ID` = 3441 AND `type` = 0 AND `Greeting` = 'To hunt a beast, one must know that beast.  One must learn and respect its ways.$B$BTo do otherwise is not to hunt.  To do otherwise is merely to kill.';
UPDATE `quest_greeting` SET `Greeting` = '对对对！你就是我要找的那个 $r！$B$B坐下！我们有很多要谈的！！' WHERE `ID` = 3446 AND `type` = 0 AND `Greeting` = 'Yes yes yes!  You''re just the $r I''m looking for!$B$BSit!  We have much to discuss!!';
UPDATE `quest_greeting` SET `Greeting` = '有什么需要我帮忙的吗，$n？不然我还有批货要去处理。' WHERE `ID` = 3453 AND `type` = 0 AND `Greeting` = 'Something I can help you with, $n? There''s a shipment I''ve got to see to otherwise.';
UPDATE `quest_greeting` SET `Greeting` = '我，阿丽尼娅·碎云，受命守护神谕林地的圣洁。' WHERE `ID` = 3519 AND `type` = 0 AND `Greeting` = 'I, Arynia Cloudsbreak, have been tasked with protecting the sanctity of the Oracle Grove.';
UPDATE `quest_greeting` SET `Greeting` = '幸会，$n。看到像你这样的 $c 积极参与保护林地，真是太好了。' WHERE `ID` = 3567 AND `type` = 0 AND `Greeting` = 'Well met, $n. It is good to see that $cs like yourself are taking an active part in protecting the groves.';
UPDATE `quest_greeting` SET `Greeting` = '风会向倾听的人低语……$B$B你听见了吗？' WHERE `ID` = 3616 AND `type` = 0 AND `Greeting` = 'The wind whispers to those who listen...$B$BDo you hear it?';
UPDATE `quest_greeting` SET `Greeting` = '黑暗势力逼近我们的边境，古老的污秽再度浮现，新的邪恶不断冒出来，打破这片土地脆弱的平衡。在这样的黑暗年代，我们都必须保持警惕。' WHERE `ID` = 3649 AND `type` = 0 AND `Greeting` = 'Dark forces encroach upon our borders, ancient taints resurface, and new evils emerge to topple the delicate balance of the land. In times of such darkness, we all must be vigilant.';
UPDATE `quest_greeting` SET `Greeting` = '你好，孩子！也许你能帮我处理一些需要料理的事情。' WHERE `ID` = 3663 AND `type` = 0 AND `Greeting` = 'Good day, $glad:lass;! Perhaps you could help me with some things that need to be taken care of.';
UPDATE `quest_greeting` SET `Greeting` = '嗯……把这根线接到这里，就能给菲兹尔坦的齿轮供电，可那样水力法兰就得另找电源……也许我可以……哦，你好！嘿，想不想帮我试试新发明？' WHERE `ID` = 3666 AND `type` = 0 AND `Greeting` = 'Hmm... I can plug this wire in here and that will power the fizzletan gear, but then the hydrophlange will need an alternate power source... Maybe I can... Oh, hello! Hey, want to help me try a new invention?';
UPDATE `quest_greeting` SET `Greeting` = '我们精灵有着悠久的历史。但愿这段历史不会回来纠缠我们。' WHERE `ID` = 3845 AND `type` = 0 AND `Greeting` = 'We elves have a long history.  Let us hope this history does not return to haunt us.';
UPDATE `quest_greeting` SET `Greeting` = '灰谷是一片生机勃勃的茂密森林。走在隐秘的小径上采集草药是件乐事，但务必小心，森林里并非没有危险。' WHERE `ID` = 3847 AND `type` = 0 AND `Greeting` = 'Ashenvale is a lush forest, brimming with life. It is a pleasure to walk down its secret paths in search of herbs, but one must take care. The forest is not without its dangers.';
UPDATE `quest_greeting` SET `Greeting` = '自然的平衡极为微妙，轻易就会被打破。你有勇气去把它拨正吗？' WHERE `ID` = 3848 AND `type` = 0 AND `Greeting` = 'The balance of nature is a delicate one, and easily tipped.  Are you brave enough to make things right?';
UPDATE `quest_greeting` SET `Greeting` = '神灵们躁动不安！' WHERE `ID` = 3995 AND `type` = 0 AND `Greeting` = 'The spirits are restless!';
UPDATE `quest_greeting` SET `Greeting` = '你得听，年轻的 $c。听听黑暗中的低语，它们会在这乱世里给你指引。' WHERE `ID` = 4046 AND `type` = 0 AND `Greeting` = 'You must listen, young $c.  Listen to the whisperings in the darkness, for they offer guidance in these troubled times.';
UPDATE `quest_greeting` SET `Greeting` = '自然之灵是值得敬畏的力量。它们会大力扶助有价值的人，也会让愚者迅速丧命。' WHERE `ID` = 4047 AND `type` = 0 AND `Greeting` = 'The spirits of nature are powers to respect.  They offer great aid to the worthy, and mete out swift death to the foolish.';
UPDATE `quest_greeting` SET `Greeting` = '石爪山的灵魂在哭泣。从山峰到河流，再到被砍伐、垂死的树木，它都在哭泣。' WHERE `ID` = 4049 AND `type` = 0 AND `Greeting` = 'The spirit of Stonetalon weeps.  It weeps from its mountain peaks, to its rivers, to its severed, dying trees.';
UPDATE `quest_greeting` SET `Greeting` = '只要我能弄到合适的材料，就能造出一些炸药，既能破坏风险投资公司的运作，还能制造混乱。$B$B我知道你佩服了，但还有更妙的……很快我就会告诉你更多。' WHERE `ID` = 4077 AND `type` = 0 AND `Greeting` = 'If I can get the proper ingredients, we can create some explosives that will not only allow me to damage the Venture''s Co.''s operations, but also cause a distraction.$B$BI know you''re impressed, but it gets better... I''ll tell you more soon enough.';
UPDATE `quest_greeting` SET `Greeting` = '你好，朋友。有什么我能帮你的？' WHERE `ID` = 4078 AND `type` = 0 AND `Greeting` = 'Hello, friend. What can I do for you?';
UPDATE `quest_greeting` SET `Greeting` = '靠近点。你我之间有些要紧事要谈。$B$B其中有些，可不想让所有人都听见……' WHERE `ID` = 4452 AND `type` = 0 AND `Greeting` = 'Come a little closer.  We have important matters to discuss, you and I.$B$BAnd some of them we don''t want everyone to hear...';
UPDATE `quest_greeting` SET `Greeting` = '脚底下留神，先生/女士。不是每个人都像 $r 那样长得高。' WHERE `ID` = 4453 AND `type` = 0 AND `Greeting` = 'Be careful where you put that foot of yours, $gmister:ma''am;.  We''re not all blessed with the lofty height of a $r.';
UPDATE `quest_greeting` SET `Greeting` = '不，长耳朵不是我的真名。我也不会告诉你真名，所以别问了。' WHERE `ID` = 4456 AND `type` = 0 AND `Greeting` = 'No, Longears isn''t my real name.  And I''m not going to tell you what it is, so don''t ask.';
UPDATE `quest_greeting` SET `Greeting` = '日子越来越长，这片土地上的纷争却看不到尽头。这用不着什么法师也算得出来。趁早拿起武器吧，$c。战争随时可能临门，要是我没看错，你看起来正是那种乐在其中的人。' WHERE `ID` = 4485 AND `type` = 0 AND `Greeting` = 'The days grow long, and still no end to the conflicts of these lands can be seen. It takes no spell caster to know that much. Take up a blade while you can, $c. War can come to our doors at any time, and if I''m not mistaken, you look to be one who revels in it.';
UPDATE `quest_greeting` SET `Greeting` = '莫克莫洛克霸主是老大。你照我说的做。' WHERE `ID` = 4500 AND `type` = 0 AND `Greeting` = 'Overlord Mok''Morokk boss. You do what I say.';
UPDATE `quest_greeting` SET `Greeting` = '我们也许没和联盟公开开战，可我们之间照样流血。' WHERE `ID` = 4791 AND `type` = 0 AND `Greeting` = 'We may not be in open war with the Alliance, but blood is still shed between us.';
UPDATE `quest_greeting` SET `Greeting` = '有些人觉得这沼泽没什么用……没什么用，他们是这么说的。' WHERE `ID` = 4792 AND `type` = 0 AND `Greeting` = 'Some people think the swamp''s no good... no good, they say.';
UPDATE `quest_greeting` SET `Greeting` = '在塞拉摩做研究是件有意思的活儿，可在这镇上想找张软床真难！' WHERE `ID` = 4794 AND `type` = 0 AND `Greeting` = 'Researching in Theramore is an interesting job, but it''s sure hard to find a soft bed in this town!';
UPDATE `quest_greeting` SET `Greeting` = '若要在这世上立足，我们就得靠钻研，靠意志去摆脱那日渐消退的人类本能。' WHERE `ID` = 5204 AND `type` = 0 AND `Greeting` = 'If we are to make our place in this world, then we will do so through study, and through the will to ignore our fading human instincts.';
UPDATE `quest_greeting` SET `Greeting` = '守望堡总是需要更多补给——给法师们做研究，也让守军保持最佳战力。' WHERE `ID` = 5393 AND `type` = 0 AND `Greeting` = 'Nethergarde keep always needs more supplies - supplies to help our mages in their research, and supplies to keep our defenders in top fighting shape.';
UPDATE `quest_greeting` SET `Greeting` = '别让这热劲儿烦着你。在荒芜之地，热是最不用操心的事。' WHERE `ID` = 5394 AND `type` = 0 AND `Greeting` = 'Don''t let the heat bother you.  In the Badlands, heat is the least of your worries.';
UPDATE `quest_greeting` SET `Greeting` = '联盟在凄凉之地利益众多，我们在这里的根基并不稳固。$B$B你愿意帮我们吗？' WHERE `ID` = 5396 AND `type` = 0 AND `Greeting` = 'The Alliance has many stakes in Desolace, and our hold here is unstable.$B$BWill you help us?';
UPDATE `quest_greeting` SET `Greeting` = '半人马部族统治着凄凉之地的荒原。他们若团结起来，会是一股可怕的力量。幸好他们并不团结，而是彼此争吵、互相攻伐。' WHERE `ID` = 5412 AND `type` = 0 AND `Greeting` = 'The centaur clans rule the wastes of Desolace.  If united, they would be a terrible force.  It is then good that the centaur clans are not united but instead bicker and war amongst themselves.';
UPDATE `quest_greeting` SET `Greeting` = '这破地方住着不太舒服，可它有历史，所以斯通纳德对某些人一定很重要。我敢打赌这就是我们留在这儿的原因。肯定不是为了风景——这儿连家都不像。' WHERE `ID` = 5591 AND `type` = 0 AND `Greeting` = 'This sty''s a little shy of comfy, but it has history, so Stonard must be important to someone. I''d gamble that''s why we stay here. It sure ain''t for the view--it don''t even look like home.';
UPDATE `quest_greeting` SET `Greeting` = '你对我有什么吩咐？' WHERE `ID` = 5598 AND `type` = 0 AND `Greeting` = 'What do you ask of me?';
UPDATE `quest_greeting` SET `Greeting` = '很高兴认识你，$c。我叫罗埃滕，是回收者公司的头儿。$B$B我和我的公会专门收购失落的货物。我们常雇勇敢的冒险者，派他们去替那些没能力或没时间的人办事。' WHERE `ID` = 5637 AND `type` = 0 AND `Greeting` = 'Pleased to meetcha, $c. Me name''s Roetten. I lead Reclaimers Incorporated.$B$BMe guild and I specialize in aquiring lost goods. We usually hire brave adventurers and send them off to finish tasks for those who aren''t able, or don''t have the time.';
UPDATE `quest_greeting` SET `Greeting` = '我在凄凉之地这边事儿多得很，$N。罗埃滕要我们替一位客户收集些材料，还得找回一些失落的东西。$B$B既然你是来帮忙的，那咱们就开始吧？' WHERE `ID` = 5638 AND `type` = 0 AND `Greeting` = 'I''ve got a lot going on out here in Desolace, $N. Roetten wants us to pick up some reagents for one of our clients as well as fetch some of these lost items.$B$BSeein'' as you''re here to help out, why don''t we get started?';
UPDATE `quest_greeting` SET `Greeting` = '萨尔最想解决的主要威胁是燃烧之刃——那些向恶魔效忠的部落成员。他们一心修炼黑暗魔法，根本不在乎萨尔对部落在此地未来的设想。' WHERE `ID` = 5641 AND `type` = 0 AND `Greeting` = 'The main threat Thrall wishes dealt with is the Burning Blade--members of the Horde that have given their loyalty to the demons. They seek to practice their dark magic and care little for Thrall''s vision of the Horde''s future here in Kalimdor.';
UPDATE `quest_greeting` SET `Greeting` = '我们唯一的希望，就是从这已经糟糕的局面里做出点好事来。' WHERE `ID` = 5767 AND `type` = 0 AND `Greeting` = 'Our only hope is to create something good from an already bad situation.';
UPDATE `quest_greeting` SET `Greeting` = '要保护自然，就得拥抱它的力量，并把这份力量展示给那些想伤害大地的人。' WHERE `ID` = 5770 AND `type` = 0 AND `Greeting` = 'If we are to protect nature, then we must embrace its strength.  And we must show this strength to those who would harm the land.';
UPDATE `quest_greeting` SET `Greeting` = '欢迎你回来，$n。' WHERE `ID` = 5887 AND `type` = 0 AND `Greeting` = 'I welcome you back, $n.';
UPDATE `quest_greeting` SET `Greeting` = '大地在召唤你，$N。去吧，要知道你的同胞为你骄傲，也为你将要成就的一切骄傲。' WHERE `ID` = 5888 AND `type` = 0 AND `Greeting` = 'The earth calls to you, $N. Go to it, and know that your brethren are proud of you and all you will accomplish.';
UPDATE `quest_greeting` SET `Greeting` = '有些人受不了大锻炉的热气，我倒觉得这热度刚刚好。而且这里是干正经锻造活儿最好的地方。' WHERE `ID` = 6031 AND `type` = 0 AND `Greeting` = 'Some can''t stand the heat of the Great Forge, but I think the heat is just right.  And it''s the best place to do some serious smithwork.';
UPDATE `quest_greeting` SET `Greeting` = '我在搞任务。一项任务！为那件最伟大的发明寻找新合金和更硬的金属！！' WHERE `ID` = 6169 AND `type` = 0 AND `Greeting` = 'I''m on quest.  A quest!  A quest for new alloys and harder metals for the greatest invention of all!!';
UPDATE `quest_greeting` SET `Greeting` = '你将被周围土地上的黑暗考验很多次，$N。为了确保你时刻有备，我们会常常交给你任务，让你保持在自身力量的巅峰。$B$B愿圣光与你同行，永葆美德。' WHERE `ID` = 6171 AND `type` = 0 AND `Greeting` = 'You will be tested many times by the darkness that surrounds our lands, $N. But to ensure you are always prepared, we will often ask tasks of you so you are at the height of your own power.$B$BGo with the Light, and remain virtuous.';
UPDATE `quest_greeting` SET `Greeting` = '圣光的圣骑士要面对许多考验，$N。放心，只要你保持热忱、坚守我们所推崇的美德，我们今后还会多次相见。' WHERE `ID` = 6179 AND `type` = 0 AND `Greeting` = 'Many tests await a paladin of the Light, $N. Be assured, our paths will cross many times in the future if you remain passionate and hold to those virtues that we praise.';
UPDATE `quest_greeting` SET `Greeting` = '穴居人与麻风侏儒游荡之地，就是我们的家——诺莫瑞根。$B$B我们的家人失散，家园被夺，四处漂泊。$B$B啊，我多么怀念诺莫瑞根无忧无虑的日子，可那样的日子再也没有了。我们必须奋起！我们必须拯救诺莫瑞根！' WHERE `ID` = 6569 AND `type` = 0 AND `Greeting` = 'Where Troggs and Leper Gnomes roam stands our home - Gnomeregan.$B$BOur families lost, our homes displaced. Scattered.$B$BOh how I long for the days of carefree Gnomeregan life, but those days are no more. We must make our stand! We must save Gnomeregan!';
UPDATE `quest_greeting` SET `Greeting` = '你需要什么，$c？我相信你跑到这片荒原来，总不会是为了闲聊吧。' WHERE `ID` = 6868 AND `type` = 0 AND `Greeting` = 'Whatcha need, $c?  I trust that you''ve come out to this wasteland for a reason other than idle chit chat.';
UPDATE `quest_greeting` SET `Greeting` = '马蒂亚斯在贫瘠之地发现了我，当时我被风险投资公司丢下等死。要不是他，我早成了猛兽的口粮。' WHERE `ID` = 6946 AND `type` = 0 AND `Greeting` = 'Mathias found me left for dead by the Venture Co. in the Barrens. Had it not been for him, I''d have been prowler fodder. ';
UPDATE `quest_greeting` SET `Greeting` = '我叫德兰·德罗弗斯，这边这个是我那个傻儿子马尔顿。你要废料，或者想卖废料，那你就得找我们！' WHERE `ID` = 6986 AND `type` = 0 AND `Greeting` = 'My name is Dran Droffers, and this over here is my dummy son Malton.  If you need salvage, or are looking to sell salvage, then we''re who you need to be talking to!';
UPDATE `quest_greeting` SET `Greeting` = '我叫比尔吉维兹尔，是加基森水务公司的总工程师。有什么我能帮你的？' WHERE `ID` = 7407 AND `type` = 0 AND `Greeting` = 'The name''s Bilgewhizzle, and I am the chief engineer of the Gadgetzan Water Company.  What can I assist you with?';
UPDATE `quest_greeting` SET `Greeting` = '很少有人能走到这么远，能过去的就更少。别成为统计数字，$N。' WHERE `ID` = 7802 AND `type` = 0 AND `Greeting` = 'So few make it this far, even fewer make it past. Do not become a statistic, $N.';
UPDATE `quest_greeting` SET `Greeting` = '有些人纳闷我们在沙漠里干什么。嗯……我要是告诉你了，你就会留下来抢我们的生意！' WHERE `ID` = 7876 AND `type` = 0 AND `Greeting` = 'Some people wonder what we''re doing out here in the desert.  Well... If I told you, then you''d stay and try to make our profits!';
UPDATE `quest_greeting` SET `Greeting` = '我们是来赚钱的。货被人偷了可赚不到钱。' WHERE `ID` = 7882 AND `type` = 0 AND `Greeting` = 'We''re here to make a profit.  And having our goods stolen is no way to make a profit.';
UPDATE `quest_greeting` SET `Greeting` = '你好，$N。也许你有空聊聊？' WHERE `ID` = 7900 AND `type` = 0 AND `Greeting` = 'Hello, $N. Perhaps you have some time to chat?';
UPDATE `quest_greeting` SET `Greeting` = '如果你是来这里诚心恳求我赐予你为我效劳的机会，那么我欢迎你。不然的话，你到一边凉快去吧。' WHERE `ID` = 8379 AND `type` = 0 AND `Greeting` = 'If you are here to beg for the privilege of working for me, then your company is quite welcome. Otherwise, there is little chance you are of any use to me.';
UPDATE `quest_greeting` SET `Greeting` = '亲爱的孩子，你来得正是时候，正好帮上卡加斯远征军。' WHERE `ID` = 9078 AND `type` = 0 AND `Greeting` = 'Dear $g boy:girl;, you have arrived just in time to assist the Kargath Expeditionary Force.\n';
UPDATE `quest_greeting` SET `Greeting` = '立正，士兵！$B$B温基！报数！' WHERE `ID` = 9177 AND `type` = 0 AND `Greeting` = 'Stand at attention, soldier!$B$BWINKY! SOUND OFF!';
UPDATE `quest_greeting` SET `Greeting` = '对体面的地精来说，追求财富是唯一的目标。$B$B嗯，也许还有……一场又大又响亮的死法！' WHERE `ID` = 9536 AND `type` = 0 AND `Greeting` = 'The quest for wealth is the only goal for a respectable goblin.$B$BWell, maybe wealth... and a big, loud death!';
UPDATE `quest_greeting` SET `Greeting` = '欢迎光临基布勒的异域宠物店！你今天能帮我什么忙？？' WHERE `ID` = 10260 AND `type` = 0 AND `Greeting` = 'Welcome to Kibler''s Exotic Pets! How can you help me today??';
UPDATE `quest_greeting` SET `Greeting` = '<余烬之息察觉到了你的存在。>' WHERE `ID` = 10321 AND `type` = 0 AND `Greeting` = '<Emberstrife acknowledges your presence.>';
UPDATE `quest_greeting` SET `Greeting` = '白峰岗起初只是个小猎营……如今人人都想在这儿开店安家。$B$B<莫特加耸了耸肩>' WHERE `ID` = 10428 AND `type` = 0 AND `Greeting` = 'Whitereach Post started off as a small hunting camp... Now, everyone wants to set up shop and call this home.$B$B<Motega shrugs his shoulder>';
UPDATE `quest_greeting` SET `Greeting` = '这一带的威胁我们没法独自应付。我们还需要一双战斗的手，$n。' WHERE `ID` = 10537 AND `type` = 0 AND `Greeting` = 'We cannot take care of all the threats in this area alone. We could use another fighting hand, $n.';
UPDATE `quest_greeting` SET `Greeting` = '我再也不觉得暖和了……' WHERE `ID` = 10926 AND `type` = 0 AND `Greeting` = 'I never feel warm anymore...';
UPDATE `quest_greeting` SET `Greeting` = '你好，$N。我是银色黎明的尼古拉斯·兹维伦霍夫公爵。' WHERE `ID` = 11039 AND `type` = 0 AND `Greeting` = 'Greetings, $N. I am Duke Nicholas Zverenhoff of the Argent Dawn.';
UPDATE `quest_greeting` SET `Greeting` = '凄凉之地其实不算太糟，只要你不介意半人马没完没了的骚扰。' WHERE `ID` = 11259 AND `type` = 0 AND `Greeting` = 'Desolace is not such a bad place, if you don''t mind the constant harassments from the centaurs.';
UPDATE `quest_greeting` SET `Greeting` = '我的商业计划里可没算进要安置巨型科多兽……也许当初我该改行去做水下编篮生意。' WHERE `ID` = 11596 AND `type` = 0 AND `Greeting` = 'My business plan never accounted for housing giant kodos... maybe I should have gone into the underwater basket weaving business instead.';
UPDATE `quest_greeting` SET `Greeting` = '凡是愿意为我们的志业牺牲的人，银色黎明都不会拒之门外。' WHERE `ID` = 16281 AND `type` = 0 AND `Greeting` = 'The Argent Dawn will turn away none who are willing to sacrifice for our cause.';
UPDATE `quest_greeting` SET `Greeting` = '巫妖王从冰封的北方对我们发动了战争，只有我们银色黎明挡在他面前。' WHERE `ID` = 16361 AND `type` = 0 AND `Greeting` = 'The Lich King has brought war against us from the frozen north, and only we of the Argent Dawn stand in his way.';
UPDATE `quest_greeting` SET `Greeting` = '你好，市民。你是来协助我们对抗天灾的吗？' WHERE `ID` = 16478 AND `type` = 0 AND `Greeting` = 'Good day to you, citizen. Have you come to aid us against the Scourge?';
UPDATE `quest_greeting` SET `Greeting` = '你好，市民。你是来协助我们对抗天灾的吗？' WHERE `ID` = 16494 AND `type` = 0 AND `Greeting` = 'Good day to you, citizen. Have you come to aid us against the Scourge?';
